#include <eigen3/Eigen/Dense>
#include <fstream>
#include <sstream>
#include <vector>
#include <string>
#include <iostream>
#include <cmath>

struct Point {
    double x;
    double y;
};

// ---------------------- Converts Points to Matrix -------------------------
Eigen::MatrixXd pointsToMatrix(const std::vector<Point>& pts)
{
    Eigen::MatrixXd M(pts.size(), 2);
    for (size_t i = 0; i < pts.size(); ++i)
    {
        M(i, 0) = pts[i].x;
        M(i, 1) = pts[i].y;
    }
    return M;
}

void writeVector(const std::string& filename, const Eigen::MatrixXd& data)
{
    std::ofstream file(filename);
    if (!file.is_open())
    {
        std::cerr << "Failed to write " << filename << "\n";
        return;
    }

    for (int i = 0; i < data.rows(); ++i)
    {
        for (int j = 0; j < data.cols(); ++j)
        {
            file << data(i, j);
            if (j < data.cols() - 1)
                file << ",";
        }
        file << "\n";
    }
}

//------------------- Waypoint Reading Function ---------------------
Eigen::MatrixXd readWaypoints(const std::string& filename)
{
    std::ifstream file(filename);
    std::vector<Eigen::Vector2d> wp;

    if (!file.is_open())
    {
        std::cerr << "Failed to open waypoints file: " << filename << "\n";
        return Eigen::MatrixXd();
    }

    std::string line;
    while (std::getline(file, line))
    {
        if (line.empty()) continue;

        // Replace commas with spaces
        for (auto &c : line) if (c == ',') c = ' ';

        std::stringstream ss(line);
        double x, y;
        if (ss >> x >> y)
            wp.emplace_back(x, y);
        else
            std::cerr << "Skipping invalid line in waypoints: " << line << "\n";
    }

    Eigen::MatrixXd waypoints(wp.size(), 2);
    for (size_t i = 0; i < wp.size(); ++i)
        waypoints.row(i) = wp[i];

    return waypoints;
}

// ---------------- Cubic spline helper ----------------
std::vector<double> cubicSpline(
    const std::vector<double>& t,
    const std::vector<double>& y,
    const std::vector<double>& tq)
{
    int n = t.size();
    std::vector<double> a(y), b(n), d(n), h(n);
    std::vector<double> alpha(n), c(n+1), l(n+1), mu(n+1), z(n+1);

    for (int i = 0; i < n - 1; i++)
        h[i] = t[i+1] - t[i];

    for (int i = 1; i < n - 1; i++)
        alpha[i] = (3.0/h[i])*(a[i+1]-a[i]) - (3.0/h[i-1])*(a[i]-a[i-1]);

    l[0] = 1.0;
    mu[0] = z[0] = 0.0;

    for (int i = 1; i < n - 1; i++) {
        l[i] = 2.0*(t[i+1]-t[i-1]) - h[i-1]*mu[i-1];
        mu[i] = h[i]/l[i];
        z[i] = (alpha[i]-h[i-1]*z[i-1])/l[i];
    }

    l[n-1] = 1.0;
    z[n-1] = c[n-1] = 0.0;

    for (int j = n - 2; j >= 0; j--) {
        c[j] = z[j] - mu[j]*c[j+1];
        b[j] = (a[j+1]-a[j])/h[j] - h[j]*(c[j+1]+2.0*c[j])/3.0;
        d[j] = (c[j+1]-c[j])/(3.0*h[j]);
    }

    // Evaluate spline
    std::vector<double> result;
    for (double xq : tq) {
        int i = std::min(int(xq) - 1, n - 2);  // convert 1-based → 0-based
        double dx = xq - t[i];
        result.push_back(a[i] + b[i]*dx + c[i]*dx*dx + d[i]*dx*dx*dx);
    }

    return result;
}

// ---------------- Micropoints function ----------------
Eigen::MatrixXd micropoints(const Eigen::MatrixXd& waypoints)
{
    int N = waypoints.rows();

    // MATLAB-style parameter t = 1:N
    std::vector<double> t(N);
    for (int i = 0; i < N; i++)
        t[i] = i + 1.0;

    // Extract x and y
    std::vector<double> x(N), y(N);
    for (int i = 0; i < N; i++) {
        x[i] = waypoints(i, 0);
        y[i] = waypoints(i, 1);
    }

    // Query points (like linspace in MATLAB)
    int numSamples = 500;
    std::vector<double> tq(numSamples);
    double step = double(N - 1) / (numSamples - 1);
    for (int i = 0; i < numSamples; i++)
        tq[i] = 1.0 + i * step;

    // Spline evaluation
    std::vector<double> xs = cubicSpline(t, x, tq);
    std::vector<double> ys = cubicSpline(t, y, tq);

    // Output as Eigen::MatrixXd (numSamples × 2)
    Eigen::MatrixXd micro(xs.size(), 2);
    for (size_t i = 0; i < xs.size(); i++) {
        micro(i, 0) = xs[i];
        micro(i, 1) = ys[i];
    }

    return micro;
}


Eigen::Vector2d findPointAtDistance(
    const Eigen::MatrixXd& points,
    const Eigen::Vector2d& point,
    double desired_dist)
{
    double desired_dist2 = desired_dist * desired_dist;

    double best_error = std::numeric_limits<double>::infinity();
    int best_idx = -1;

    for (int i = 0; i < points.rows(); ++i)
    {
        double dx = points(i, 0) - point(0);
        double dy = points(i, 1) - point(1);
        double dist2 = dx*dx + dy*dy;

        double error = std::abs(dist2 - desired_dist2);

        if (error < best_error)
        {
            best_error = error;
            best_idx = i;
        }
    }

    return points.row(best_idx);
}

Eigen::Vector4d PP_single(const Eigen::Vector3d& State, const Eigen::MatrixXd& waypoints, double linVel, const Eigen::Vector2d& target)
{
    // ------------------ Create Micropoints -------------------------
    auto micro = micropoints(waypoints);

    writeVector("micropoints.txt", micro);
    Eigen::MatrixXd microp = readWaypoints("micropoints.txt");

    // ------------------ Identify goal point ------------------------
    const Eigen::Vector2d backWheel_pos = {State[0] + std::cos(State[2]) * 0.15,
                                           State[1] + std::cos(State[2]) * 0.15};

    double LA = 0.5;

    // double closest_idx = findClosestPoint(microp, backWheel_pos);
    //Eigen::Vector2d target = findPointAtDistance(microp, backWheel_pos, LA);

    double dy = target(1) - backWheel_pos(1);
    double dx = target(0) - backWheel_pos(0);

    double alpha = std::atan(dy / dx) - State[2];                     
    alpha = std::atan(std::sin(alpha) / std::cos(alpha)); // normalize angle to [-pi, pi]

    double kappa = (2 * std::sin(alpha)) / LA;
    double angVel = kappa * linVel;

    // ------------------ Store Controls in 3x1 Vector ----------------
    Eigen::Vector4d controls;

    controls << linVel, angVel, backWheel_pos(0), backWheel_pos(1);

    return controls;
}

